rustc_index :: newtype_index ! { #[doc = " A node in the MIR [control-flow graph][CFG]."] #[doc = ""] #[doc = " There are no branches (e.g., `if`s, function calls, etc.) within a basic block, which makes"] #[doc = " it easier to do [data-flow analyses] and optimizations. Instead, branches are represented"] #[doc = " as an edge in a graph between basic blocks."] #[doc = ""] #[doc = " Basic blocks consist of a series of [statements][Statement], ending with a"] #[doc = " [terminator][Terminator]. Basic blocks can have multiple predecessors and successors,"] #[doc = " however there is a MIR pass ([`CriticalCallEdges`]) that removes *critical edges*, which"] #[doc = " are edges that go from a multi-successor node to a multi-predecessor node. This pass is"] #[doc = " needed because some analyses require that there are no critical edges in the CFG."] #[doc = ""] #[doc = " Note that this type is just an index into [`Body.basic_blocks`](Body::basic_blocks);"] #[doc = " the actual data that a basic block holds is in [`BasicBlockData`]."] #[doc = ""] #[doc = " Read more about basic blocks in the [rustc-dev-guide][guide-mir]."] #[doc = ""] #[doc = " [CFG]: https://rustc-dev-guide.rust-lang.org/appendix/background.html#cfg"] #[doc = " [data-flow analyses]:"] #[doc = "     https://rustc-dev-guide.rust-lang.org/appendix/background.html#what-is-a-dataflow-analysis"] #[doc = " [`CriticalCallEdges`]: ../../rustc_mir_transform/add_call_guards/enum.AddCallGuards.html#variant.CriticalCallEdges"] #[doc = " [guide-mir]: https://rustc-dev-guide.rust-lang.org/mir/"] #[derive (HashStable)] #[encodable] #[orderable] #[debug_format = "bb{}"] pub struct BasicBlock { const START_BLOCK = 0 ;}
}